//! Build-time switches for the Linux platform layer.
//!
//! These are generated by `build.zig` from what pkg-config reports on the build
//! machine, so the module compiles against the display libraries the host
//! actually has instead of assuming a fixed set. A host without Wayland still
//! builds; `Display.probe` then reports the absence at runtime, which is the
//! condition the developer needs to see.

const build_options = @import("build_options");

pub const have_wayland: bool = build_options.have_wayland;
pub const have_xcb: bool = build_options.have_xcb;
